{
  "mcp": {
    "sentry": {
      "type": "remote",
      "url": "https://mcp.sentry.dev/mcp",
      "enabled": true
    },
    "linear": {
      "type": "remote",
      "url": "https://mcp.linear.app/mcp",
      "enabled": true
    }
  },
  "permission": {
    "sentry_*": "deny",
    "linear_*": "deny"
  },
  "agent": {
    "ops-agent": {
      "description": "Operations agent with Sentry access",
      "mode": "subagent",
      "permission": {
        "sentry_*": "allow"
      }
    },
    "pm-agent": {
      "description": "Project management agent with Linear access",
      "mode": "subagent",
      "permission": {
        "linear_*": "allow"
      }
    }
  }
}

# 查看 MCP Server 状态
curl http://localhost:4096/mcp

# 动态添加 MCP Server
curl -X POST http://localhost:4096/mcp -d '{
  "name": "my-new-mcp",
  "config": {
    "type": "local",
    "command": ["npx", "-y", "my-mcp-server"]
  }
}'
